def load() -> pd.DataFrame:
    with open('data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv', 'r', encoding='cp1252') as f:
        lines = f.readlines()
    for i, line in enumerate(lines[:15]):
        print(f"Row {i}: {repr(line)}")
    return pd.DataFrame({'raw_inspection': [str(lines[:15])]})
